import styles from './InvestmentList.module.css';

const InvestmentList = ({ investments, onEditInvestment }) => {
  return (
    <div className={styles.list}>
      {investments.map((investment, index) => (
        <div key={index} className={styles.item}>
          <p><strong>Marca:</strong> {investment.brand}</p>
          <p><strong>Procesador:</strong> {investment.processor}</p>
          <p><strong>Generación:</strong> {investment.generation}</p>
          <p><strong>Costo Inicial:</strong> ${investment.initialCost}</p>
          <p><strong>Precio de Venta:</strong> ${investment.salePrice}</p>
          <p><strong>Ganancia:</strong> ${investment.profit}</p>
          <button onClick={() => onEditInvestment(index)}>Editar</button>
        </div>
      ))}
    </div>
  );
};

export default InvestmentList;
